export * as featureFlagService from "./feature-flag-service";
export * as invitationService from "./invitation-service";
export * as issueService from "./issue-service";
export * as labelService from "./label-service";
export * as memberService from "./member-service";
export * as notificationService from "./notification-service";
export * as organizationService from "./organization-service";
export * as projectService from "./project-service";
export * as searchService from "./search-service";
export * as sessionService from "./session-service";
export * as usageService from "./usage-service";
export * as webhookService from "./webhook-service";

export {
  registerEventHandlers,
  unregisterEventHandlers,
} from "./event-registry";

export type { ActivityRecordInput } from "./activity-service";
export type {
  EmailTemplate,
  OutgoingEmail,
  RenderedEmail,
} from "./email-service";
export type { NotificationPayload } from "./notification-service";
export type { SearchHit } from "./search-service";
---NOTIF
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: `/issues/${payload.issueId}`,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: `/issues/${payload.issueId}`,
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });
}

registerFanOut();
---USAGE
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
---WEBHOOK

/**
 * Fans domain events out into the delivery table. Each org's endpoints
 * declare which event types they want, so an endpoint only ever receives what
 * it subscribed to; the job drains the rows afterwards.
 */
export function registerWebhookListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("webhook.delivery_requested", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        payload.eventType,
        JSON.stringify(payload.payload),
      );
    }),
    subscribe("issue.created", async (payload) => {
      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
    }),
    subscribe("issue.status_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "issue.status_changed",
        JSON.stringify(payload),
      );
    }),
    subscribe("comment.created", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "comment.created",
        JSON.stringify(payload),
      );
    }),
    subscribe("billing.plan_changed", async (payload) => {
      await enqueueForOrg(
        payload.orgId,
        "billing.plan_changed",
        JSON.stringify(payload),
      );
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

---EVENTTYPES
}

export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;
---TESTBUS
/** Subscribe/emit/unsubscribe, handler isolation and `subscriberCount`. */
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  emit,
  emitAndForget,
  onHandlerError,
  resetEventBus,
  subscribe,
  subscribeOnce,
  subscriberCount,
} from "@/lib/event-bus";
import type { IssueId, IsoTimestamp, ProjectId } from "@/types/common";
import type { TaskflowEventMap } from "@/types/event";
import { ALICE, ORG_A } from "../helpers/factories";

function issueCreated(
  title = "Fix the sign-up link",
): TaskflowEventMap["issue.created"] {
  return {
    orgId: ORG_A,
    actorId: ALICE,
    occurredAt: "2026-03-15T12:00:00.000Z" as IsoTimestamp,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    title,
    assigneeId: null,
    priority: "medium",
  };
}

afterEach(() => {
  resetEventBus();
});

describe("lib/event-bus", () => {
  it("delivers a payload to every subscriber of that type only", async () => {
    const onCreated = vi.fn();
    const onArchived = vi.fn();
    subscribe("issue.created", onCreated);
    subscribe("issue.archived", onArchived);

    await emit("issue.created", issueCreated());

    expect(onCreated).toHaveBeenCalledTimes(1);
    expect(onCreated.mock.calls[0]?.[0]).toMatchObject({ title: "Fix the sign-up link" });
    expect(onArchived).not.toHaveBeenCalled();
  });

  it("is a no-op when nothing subscribes", async () => {
    await expect(emit("issue.created", issueCreated())).resolves.toBeUndefined();
    expect(subscriberCount("issue.created")).toBe(0);
  });

  it("stops delivering after the returned unsubscribe is called", async () => {
    const handler = vi.fn();
    const off = subscribe("issue.created", handler);
    expect(subscriberCount("issue.created")).toBe(1);

    off();
    expect(subscriberCount("issue.created")).toBe(0);
    await emit("issue.created", issueCreated());
    expect(handler).not.toHaveBeenCalled();
  });

  it("delivers a `subscribeOnce` handler exactly once", async () => {
    const handler = vi.fn();
    subscribeOnce("issue.created", handler);

    await emit("issue.created", issueCreated("first"));
    await emit("issue.created", issueCreated("second"));

    expect(handler).toHaveBeenCalledTimes(1);
    expect(subscriberCount("issue.created")).toBe(0);
  });

  it("isolates a throwing handler: siblings still run and emit resolves", async () => {
    const sink = vi.fn();
    onHandlerError(sink);
    subscribe("issue.created", () => {
      throw new Error("handler exploded");
    });
    const survivor = vi.fn();
    subscribe("issue.created", survivor);

    await expect(emit("issue.created", issueCreated())).resolves.toBeUndefined();
    expect(survivor).toHaveBeenCalledTimes(1);
    expect(sink).toHaveBeenCalledTimes(1);
    expect(sink.mock.calls[0]?.[0]).toBe("issue.created");
  });

  it("reports a rejected async handler to the error sinks", async () => {
    const sink = vi.fn();
    onHandlerError(sink);
    subscribe("issue.created", async () => {
      await Promise.reject(new Error("async boom"));
    });

    await emit("issue.created", issueCreated());
    expect(sink).toHaveBeenCalledTimes(1);
  });

  it("awaits async handlers before resolving", async () => {
    const order: string[] = [];
    subscribe("issue.created", async () => {
      await new Promise((resolve) => setTimeout(resolve, 5));
      order.push("handler");
    });

    await emit("issue.created", issueCreated());
    order.push("after-emit");
    expect(order).toEqual(["handler", "after-emit"]);
  });

  it("emitAndForget returns synchronously but still delivers", async () => {
    const handler = vi.fn();
    subscribe("issue.created", handler);

    expect(emitAndForget("issue.created", issueCreated())).toBeUndefined();
    await Promise.resolve();
    await Promise.resolve();
    expect(handler).toHaveBeenCalledTimes(1);
  });

  it("counts each distinct handler once", () => {
    const handler = vi.fn();
    subscribe("issue.created", handler);
    subscribe("issue.created", handler);
    expect(subscriberCount("issue.created")).toBe(1);

    subscribe("issue.created", vi.fn());
    expect(subscriberCount("issue.created")).toBe(2);
  });
});

